              leaves += 'M' + x.toFixed(1) + ' ' + y.toFixed(1) + 'q' + (-w*.55).toFixed(1) + ' ' + (-w*.48).toFixed(1) + ' ' + (-w).toFixed(1) + ' ' + (-w*.12).toFixed(1) + 'q' + (w*.3).toFixed(1) + ' ' + (w*.64).toFixed(1) + ' ' + w.toFixed(1) + ' ' + (w*.12).toFixed(1) + 'z';
