        if (isUpper)          pitch += 350;
        if (hasRepeatedVowel) pitch += 500;
        if (hasBang)          pitch += 250;
        var prevSyl = si > 0 ? syllables[si - 1] : null;
        var isRepeatOfPrev = prevSyl && prevSyl.replace(/[^a-zA-Z]/g, '').toLowerCase() === letters.toLowerCase();
