          'aria-label': labelFor ? labelFor(o.name, o.sp.len) : o.name, 'aria-pressed': on ? 'true' : 'false', 'data-owl': o.name, 'data-owl-len': o.sp.len,
          onClick: function() { onPick(o.i); },
